void XPLMCreateAvionics_t_to_table(lua_State* L, XPLMCreateAvionics_t const& src)
{
	lua_newtable(L);

	lua_pushstring(L, "screenWidth");
	lua_pushinteger(L, src.screenWidth);
	lua_settable(L, -3);

	lua_pushstring(L, "screenHeight");
	lua_pushinteger(L, src.screenHeight);
	lua_settable(L, -3);

	lua_pushstring(L, "bezelWidth");
	lua_pushinteger(L, src.bezelWidth);
	lua_settable(L, -3);

	lua_pushstring(L, "bezelHeight");
	lua_pushinteger(L, src.bezelHeight);
	lua_settable(L, -3);

	lua_pushstring(L, "screenOffsetX");
	lua_pushinteger(L, src.screenOffsetX);
	lua_settable(L, -3);

	lua_pushstring(L, "screenOffsetY");
	lua_pushinteger(L, src.screenOffsetY);
	lua_settable(L, -3);

	lua_pushstring(L, "drawOnDemand");
	lua_pushinteger(L, src.drawOnDemand);
	lua_settable(L, -3);

	lua_pushstring(L, "bezelDrawCallback");
	luaL_loadstring(L, "function() end");
	lua_settable(L, -3);

	lua_pushstring(L, "drawCallback");
	luaL_loadstring(L, "function() end");
	lua_settable(L, -3);

	lua_pushstring(L, "deviceID");
	lua_pushstring(L, src.deviceID);
	lua_settable(L, -3);

	lua_pushstring(L, "deviceName");
	lua_pushstring(L, src.deviceName);
	lua_settable(L, -3);

	lua_pushstring(L, "refcon");
	xlua_pushuserdata<void*>(L, src.refcon);
	lua_settable(L, -3);
}

